extends Node3D   # Display LaserScan (PC, rclgd). Hijo del nodo del frame_id del scan.
@export var color_intensidad := true
@export var rango_intensidad := Vector2(0.0, 4096.0)   # RViz: Min/Max Intensity
@export var decay_s := 0.0          # 0 = solo el último barrido (RViz Decay Time)
@export var tam_px := 3.0
var _sub: RosSubscriber
var _dirs := PackedVector2Array(); var _clave := Vector3.INF
var _mat := StandardMaterial3D.new()
var _lut := PackedColorArray(range(256).map(func(k): return Color.from_hsv(0.8333 * (1.0 - k / 255.0), 1, 1)))

func iniciar(nodo: RosNode, topic: String) -> void:
	_mat.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED; _mat.vertex_color_use_as_albedo = true
	_mat.use_point_size = true; _mat.point_size = tam_px
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)
	_sub = nodo.create_subscription(topic, "sensor_msgs/msg/LaserScan", _on_scan, qos)

func _on_scan(msg) -> void:
	var r: PackedFloat32Array = msg.ranges; var it: PackedFloat32Array = msg.intensities
	var clave := Vector3(msg.angle_min, msg.angle_increment, r.size())
	if clave != _clave:   # tabla de direcciones: cos/sin solo si cambia la geometría
		_clave = clave; _dirs.resize(r.size())
		for i in r.size(): _dirs[i] = Vector2.from_angle(msg.angle_min + i * msg.angle_increment)
	var pts := PackedVector3Array(); var col := PackedColorArray()
	var esc := 255.0 / maxf(rango_intensidad.y - rango_intensidad.x, 1e-6)
	for i in r.size():
		if not (r[i] >= msg.range_min and r[i] <= msg.range_max): continue   # ±Inf y NaN fuera (REP-117)
		var d := _dirs[i] * r[i]
		pts.append(Vector3(-d.y, 0.0, -d.x))   # ROS (x, y, 0) → Godot (−y, 0, −x)
		col.append(_lut[clampi(int((it[i] - rango_intensidad.x) * esc), 0, 255)] if color_intensidad and i < it.size() else Color.RED)
	var a := []; a.resize(Mesh.ARRAY_MAX); a[Mesh.ARRAY_VERTEX] = pts; a[Mesh.ARRAY_COLOR] = col
	var mi := MeshInstance3D.new(); mi.material_override = _mat; mi.mesh = ArrayMesh.new()
	if pts.size() > 0: mi.mesh.add_surface_from_arrays(Mesh.PRIMITIVE_POINTS, a)
	add_child(mi)
	if decay_s > 0.0:   # congelado en el mundo donde se midió; RViz lo hace en el fixed frame
		mi.top_level = true; mi.global_transform = global_transform
		get_tree().create_timer(decay_s).timeout.connect(mi.queue_free)
	for c in get_children(): if c != mi and not c.top_level: c.queue_free()

extends Node2D   # LaserScan en la Vita: capa 2D, UN lote por mensaje (H16-H17). Planta o superpuesto.
@export var escala_px := 40.0   # px por metro en la vista de planta
@export var lado_px := 3.0
@export var color := Color(1, 0.2, 0.2)
var _sub: RosSubscriber
var _idx := PackedInt32Array(); var _v := PackedVector2Array(); var _c := PackedColorArray()
var _dirs := PackedVector2Array(); var _clave := Vector3.INF

func iniciar(nodo: RosNode, topic: String) -> void:
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)   # ≤ 106 rayos con frame corto = ≤ 488 B
	_sub = nodo.create_subscription(topic, "sensor_msgs/msg/LaserScan", _on_scan, qos)

func _on_scan(msg) -> void:   # también vale para /vita/scan_compacto tras desempaquetar
	var r: PackedFloat32Array = msg.ranges
	var clave := Vector3(msg.angle_min, msg.angle_increment, r.size())
	if clave != _clave:
		_clave = clave; _dirs.resize(r.size())
		for i in r.size(): _dirs[i] = Vector2.from_angle(msg.angle_min + i * msg.angle_increment)
	_v.resize(r.size() * 3); _c.resize(r.size() * 3); var n := 0
	for i in r.size():
		if not (r[i] >= msg.range_min and r[i] <= msg.range_max): continue
		var d := _dirs[i] * r[i] * escala_px; var p := Vector2(-d.y, -d.x)   # ROS x arriba, y izquierda
		_v[n] = p + Vector2(0, -lado_px); _v[n + 1] = p + Vector2(lado_px, lado_px); _v[n + 2] = p + Vector2(-lado_px, lado_px)
		_c[n] = color; _c[n + 1] = color; _c[n + 2] = color; n += 3
	_v.resize(n); _c.resize(n)
	if _idx.size() != n: _idx = PackedInt32Array(range(n))
	queue_redraw()   # solo al llegar un mensaje, nunca cada fotograma

func _draw() -> void:
	if _v.size() > 0: RenderingServer.canvas_item_add_triangle_array(get_canvas_item(), _idx, _v, _c)

extends "res://scan_pc.gd"   # MultiEchoLaserScan (PC): reutiliza el display LaserScan eligiendo un eco.
@export_enum("primero", "ultimo", "mas_fuerte", "todos") var eco := "primero"
var _tmp := {}   # LaserScan «aplanado» que se pasa a _on_scan

func iniciar(nodo: RosNode, topic: String) -> void:
	super.iniciar(nodo, topic)   # crea el material y una suscripción LaserScan que se sustituye:
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)
	_sub = nodo.create_subscription(topic, "sensor_msgs/msg/MultiEchoLaserScan", _on_multi, qos)

func _on_multi(msg) -> void:
	var r := PackedFloat32Array(); var it := PackedFloat32Array(); var inc: float = msg.angle_increment
	var rs: Array = msg.ranges; var ins: Array = msg.intensities   # Array de RosMsg LaserEcho (lento: 1 objeto por haz)
	var n := rs.size(); var cada := 1
	for i in n:
		var e: PackedFloat32Array = rs[i].echoes
		var ei: PackedFloat32Array = ins[i].echoes if i < ins.size() else PackedFloat32Array()
		var idx := range(e.size()) if eco == "todos" else [0 if eco == "primero" else (e.size() - 1 if eco == "ultimo" else Array(ei).find(Array(ei).max()) if ei.size() else 0)]
		for j in idx:
			if j >= 0 and j < e.size(): r.append(e[j]); it.append(ei[j] if j < ei.size() else 0.0)
		cada = maxi(cada, idx.size())
	# con «todos», cada haz aporta varios ecos: se repite el ángulo (aproximación: incremento / cada)
	_on_scan({"ranges": r, "intensities": it, "angle_min": msg.angle_min, "angle_increment": inc / cada,
		"range_min": msg.range_min, "range_max": msg.range_max})

extends MeshInstance3D   # Display PointCloud2 (PC, rclgd). Hijo del nodo del frame_id.
@export var campo_color := "intensity"   # "" = plano, "z" = eje, "rgb" = empaquetado
@export var rango_color := Vector2(0.0, 1.0)   # min/max del campo (RViz: autocompute)
@export var max_puntos := 60000
@export var tam_px := 3.0
var _sub: RosSubscriber
var _lut := PackedColorArray(range(256).map(func(k): return Color.from_hsv(0.8333 * (1.0 - k / 255.0), 1, 1)))

func iniciar(nodo: RosNode, topic: String) -> void:
	basis = Basis(Vector3(0, 0, -1), Vector3(-1, 0, 0), Vector3(0, 1, 0))  # ROS→Godot sin bucle
	var m := StandardMaterial3D.new()
	m.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED; m.vertex_color_use_as_albedo = true
	m.use_point_size = true; m.point_size = tam_px   # PRIMITIVE_POINTS con tamaño en píxeles
	material_override = m
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)   # sensor data
	_sub = nodo.create_subscription(topic, "sensor_msgs/msg/PointCloud2", _on_nube, qos)

func _on_nube(msg) -> void:
	var off := {}
	for f in msg.fields: off[f.name] = f.offset   # datatype 7 = FLOAT32 asumido (comprobar)
	var data: PackedByteArray = msg.data
	if msg.is_bigendian: data.bswap32()           # válido si todos los campos son de 4 B
	var ps: int = msg.point_step
	var total: int = msg.width * msg.height
	var paso := maxi(1, ceili(float(total) / max_puntos))   # diezmado uniforme
	var ox: int = off["x"]; var oy: int = off["y"]; var oz: int = off["z"]; var oc: int = off.get(campo_color, -1)
	var pts := PackedVector3Array(); var col := PackedColorArray()
	var esc := 255.0 / maxf(rango_color.y - rango_color.x, 1e-6)
	for i in range(0, total, paso):
		var o := i * ps
		var p := Vector3(data.decode_float(o + ox), data.decode_float(o + oy), data.decode_float(o + oz))
		if not p.is_finite(): continue   # is_dense = false → NaN
		pts.append(p)
		if campo_color == "rgb" and oc >= 0: var c := data.decode_u32(o + oc); col.append(Color8(c >> 16 & 255, c >> 8 & 255, c & 255))
		elif oc >= 0: col.append(_lut[clampi(int((data.decode_float(o + oc) - rango_color.x) * esc), 0, 255)])
		else: col.append(Color.WHITE)
	var a := []; a.resize(Mesh.ARRAY_MAX); a[Mesh.ARRAY_VERTEX] = pts; a[Mesh.ARRAY_COLOR] = col
	var am := ArrayMesh.new()
	if pts.size() > 0: am.add_surface_from_arrays(Mesh.PRIMITIVE_POINTS, a)
	mesh = am

extends Node2D   # PointCloud2 en la Vita: el relay la convierte en /vita/nube2d (Int16 xyz cm, ≤ 78 pts/trozo).
@export var escala_px := 40.0
@export var alturas := Vector2(-0.2, 2.0)   # banda de color por z (m), como el Axis color de RViz
@export var lado_px := 2.0
var _sub: RosSubscriber; var _trozos := {}   # trozo → [PackedVector2Array, PackedColorArray]
var _lut := PackedColorArray(range(16).map(func(k): return Color.from_hsv(0.66 * (1.0 - k / 15.0), 1, 1)))

func iniciar(nodo: RosNode, topic := "/vita/nube2d") -> void:
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)
	_sub = nodo.create_subscription(topic, "std_msgs/msg/Int16MultiArray", _on_trozo, qos)

func _on_trozo(msg) -> void:   # formato propuesto: [seq, trozo, n_trozos, x0, y0, z0, …] en cm
	var d: PackedInt32Array = msg.data   # int16[] llega como PackedInt32Array (H25)
	if d.size() < 3: return
	if d[1] == 0: _trozos.clear()       # trozo 0 = nueva nube
	var v := PackedVector2Array(); var c := PackedColorArray()
	var esc := 15.0 / (alturas.y - alturas.x)
	for i in range(3, d.size() - 2, 3):
		var p := Vector2(-d[i + 1], -d[i]) * (escala_px / 100.0)   # planta: ROS x arriba, y izquierda
		var col := _lut[clampi(int((d[i + 2] / 100.0 - alturas.x) * esc), 0, 15)]
		v.append_array([p + Vector2(0, -lado_px), p + Vector2(lado_px, lado_px), p + Vector2(-lado_px, lado_px)])
		c.append_array([col, col, col])
	_trozos[d[1]] = [v, c]
	queue_redraw()

func _draw() -> void:   # un lote por trozo (≤ 6 lotes con 468 puntos); todo con color plano → se funde (H16)
	for t in _trozos.values():
		RenderingServer.canvas_item_add_triangle_array(get_canvas_item(), PackedInt32Array(range(t[0].size())), t[0], t[1])

extends "res://nube_pc2.gd"   # sensor_msgs/PointCloud (obsoleto): Point32[] + ChannelFloat32[].
# Recomendado: convertirla a PointCloud2 fuera de Godot (nodo point_cloud_converter / relay); esto es el respaldo.

func iniciar(nodo: RosNode, topic: String) -> void:
	super.iniciar(nodo, topic)   # material y ejes; se sustituye la suscripción:
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)
	_sub = nodo.create_subscription(topic, "sensor_msgs/msg/PointCloud", _on_vieja, qos)

func _on_vieja(msg) -> void:
	var puntos: Array = msg.points   # Array de RosMsg Point32: un objeto por punto (caro, ≈ 1 µs+/pt en PC)
	var canal := PackedFloat32Array()
	for ch in msg.channels:
		if ch.name == campo_color: canal = ch.values   # float32[] → PackedFloat32Array (memcpy)
	var pts := PackedVector3Array(); var col := PackedColorArray()
	var esc := 255.0 / maxf(rango_color.y - rango_color.x, 1e-6)
	var paso := maxi(1, ceili(float(puntos.size()) / max_puntos))
	for i in range(0, puntos.size(), paso):
		var p := Vector3(puntos[i].x, puntos[i].y, puntos[i].z)
		if not p.is_finite(): continue
		pts.append(p)
		col.append(_lut[clampi(int((canal[i] - rango_color.x) * esc), 0, 255)] if i < canal.size() else Color.WHITE)
	var a := []; a.resize(Mesh.ARRAY_MAX); a[Mesh.ARRAY_VERTEX] = pts; a[Mesh.ARRAY_COLOR] = col
	var am := ArrayMesh.new()
	if pts.size() > 0: am.add_surface_from_arrays(Mesh.PRIMITIVE_POINTS, a)
	mesh = am

extends TextureRect   # Display Image (PC, rclgd; en la Vita solo rgb8/mono8 pequeñas). Capa HUD.
@export var rango := Vector2(0.0, 5.0)   # profundidad en m (RViz: Normalize Range = off)
const FMT := {"rgb8": Image.FORMAT_RGB8, "rgba8": Image.FORMAT_RGBA8, "bgr8": Image.FORMAT_RGB8,
	"bgra8": Image.FORMAT_RGBA8, "mono8": Image.FORMAT_L8, "8UC1": Image.FORMAT_L8, "8UC3": Image.FORMAT_RGB8,
	"bayer_rggb8": Image.FORMAT_L8, "bayer_bggr8": Image.FORMAT_L8, "bayer_gbrg8": Image.FORMAT_L8,
	"bayer_grbg8": Image.FORMAT_L8, "mono16": Image.FORMAT_R16, "16UC1": Image.FORMAT_R16, "32FC1": Image.FORMAT_RF}
const SH := "shader_type canvas_item; uniform int modo; uniform vec2 rango; uniform sampler2D paleta : filter_nearest;
void fragment(){ vec4 c = texture(TEXTURE, UV);
 if (modo == 1) { COLOR = vec4(c.bgr, c.a); }   // bgr8/bgra8: intercambio de canales en GPU
 else if (modo >= 2) { float z = modo == 2 ? c.r * 65.535 : c.r;   // 16UC1 en mm (unorm) / 32FC1 en m
  COLOR = (z > 0.0 && !isinf(z)) ? texture(paleta, vec2(clamp((z - rango.x) / (rango.y - rango.x), 0.0, 1.0), 0.5)) : vec4(0.0); } }"
var _sub: RosSubscriber
var _tex: ImageTexture
var _mat := ShaderMaterial.new()

func iniciar(nodo: RosNode, topic: String) -> void:
	_mat.shader = Shader.new(); _mat.shader.code = SH; material = _mat
	var g := GradientTexture1D.new(); g.gradient = Gradient.new()   # paleta tipo «turbo»: azul→rojo
	g.gradient.colors = PackedColorArray([Color.DARK_BLUE, Color.CYAN, Color.YELLOW, Color.RED])
	g.gradient.offsets = PackedFloat32Array([0.0, 0.33, 0.66, 1.0]); _mat.set_shader_parameter("paleta", g)
	stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_CENTERED
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)
	_sub = nodo.create_subscription(topic, "sensor_msgs/msg/Image", _on_imagen, qos)

func _on_imagen(msg) -> void:
	var e: String = msg.encoding
	if not FMT.has(e) or msg.is_bigendian: return   # yuv422/nv21/rgb16…: relay o hueco (ver borrador)
	var w: int = msg.width; var h: int = msg.height; var data: PackedByteArray = msg.data
	var bpp: int = {Image.FORMAT_L8: 1, Image.FORMAT_RGB8: 3, Image.FORMAT_RGBA8: 4, Image.FORMAT_R16: 2, Image.FORMAT_RF: 4}[FMT[e]]
	if msg.step != w * bpp: return   # filas con relleno: recortar fila a fila (raro; hueco)
	var img := Image.create_from_data(w, h, false, FMT[e], data)
	_mat.set_shader_parameter("modo", 1 if e.begins_with("bgr") else (2 if FMT[e] == Image.FORMAT_R16 else (3 if e == "32FC1" else 0)))
	_mat.set_shader_parameter("rango", rango)
	if _tex == null or _tex.get_size() != Vector2(w, h) or _tex.get_format() != img.get_format():
		_tex = ImageTexture.create_from_image(img); texture = _tex   # 1.ª vez o cambio de tamaño
	else: _tex.update(img)   # sin realojar (H19 en la Vita: convierte a RGBA8)

