extends TextureRect   # Image yuv422/uyvy/yuyv/yuv422_yuy2 (PC): 4 B = 2 píxeles → textura RGBA8 de ancho/2 + shader.
const SH := "shader_type canvas_item; uniform bool uyvy; uniform sampler2D tex : filter_nearest; uniform float ancho;
void fragment(){ vec4 q = texture(tex, UV);   // yuyv: (Y0,U,Y1,V); uyvy: (U,Y0,V,Y1)
 bool impar = mod(floor(UV.x * ancho), 2.0) > 0.5;
 float y = uyvy ? (impar ? q.a : q.g) : (impar ? q.b : q.r); float u = (uyvy ? q.r : q.g) - 0.5; float v = (uyvy ? q.b : q.a) - 0.5;
 COLOR = vec4(y + 1.402 * v, y - 0.344 * u - 0.714 * v, y + 1.772 * u, 1.0); }"   # BT.601 de rango completo [I]
var _sub: RosSubscriber; var _tex: ImageTexture; var _mat := ShaderMaterial.new()

func iniciar(nodo: RosNode, topic: String) -> void:
	_mat.shader = Shader.new(); _mat.shader.code = SH; material = _mat
	texture = PlaceholderTexture2D.new()   # el TextureRect solo da el rectángulo; la imagen va en «tex»
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)
	_sub = nodo.create_subscription(topic, "sensor_msgs/msg/Image", _on_imagen, qos)

func _on_imagen(msg) -> void:
	var e: String = msg.encoding
	if not e in ["yuv422", "uyvy", "yuyv", "yuv422_yuy2"] or msg.step != msg.width * 2: return
	var img := Image.create_from_data(msg.width / 2, msg.height, false, Image.FORMAT_RGBA8, msg.data)
	if _tex == null or _tex.get_size() != Vector2(img.get_size()): _tex = ImageTexture.create_from_image(img)
	else: _tex.update(img)
	(texture as PlaceholderTexture2D).size = Vector2(msg.width, msg.height)
	_mat.set_shader_parameter("tex", _tex); _mat.set_shader_parameter("ancho", float(msg.width))
	_mat.set_shader_parameter("uyvy", e in ["yuv422", "uyvy"])   # yuv422 = UYVY en image_encodings.hpp

extends TextureRect   # Display CompressedImage jpeg/png (PC y Vita: el motor decodifica, H22). Capa HUD.
var _sub: RosSubscriber
var _tex: ImageTexture
var _img := Image.new()

func iniciar(nodo: RosNode, topic: String, fiable := false) -> void:
	stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_CENTERED
	var qos := RosQoS.new()   # Vita: JPEG 160×120 ≈ 3 KB → fiable (≤ ~7,5 KiB), nunca BE (> 488 B)
	qos.set_reliability(RosQoS.RELIABLE if fiable else RosQoS.BEST_EFFORT)   # método: la Vita no expone la propiedad
	_sub = nodo.create_subscription(topic, "sensor_msgs/msg/CompressedImage", _on_jpeg, qos)

func _on_jpeg(msg) -> void:
	var f: String = msg.format   # "jpeg", "png", "rgb8; jpeg compressed bgr8", "16UC1; compressedDepth png"
	if "compressedDepth" in f: return   # PNG de 16 bit: el cargador de Godot lo baja a 8 bit (hueco)
	var data: PackedByteArray = msg.data
	var err := _img.load_png_from_buffer(data) if "png" in f else _img.load_jpg_from_buffer(data)
	if err != OK: return
	if _tex == null or _tex.get_size() != Vector2(_img.get_size()):
		_tex = ImageTexture.create_from_image(_img); texture = _tex
	else: _tex.update(_img)

extends TextureRect   # Display CompressedImage jpeg/png (PC y Vita: el motor decodifica, H22). Capa HUD.
var _sub: RosSubscriber
