	_sub = nodo.create_subscription(topic, "sensor_msgs/msg/CompressedImage", _on_jpeg, qos)

func _on_jpeg(msg) -> void:
	var f: String = msg.format   # "jpeg", "png", "rgb8; jpeg compressed bgr8", "16UC1; compressedDepth png"
	if "compressedDepth" in f: return   # PNG de 16 bit: el cargador de Godot lo baja a 8 bit (hueco)
	var data: PackedByteArray = msg.data
	var err := _img.load_png_from_buffer(data) if "png" in f else _img.load_jpg_from_buffer(data)
	if err != OK: return
	if _tex == null or _tex.get_size() != Vector2(_img.get_size()):
		_tex = ImageTexture.create_from_image(_img); texture = _tex
	else: _tex.update(_img)

extends MeshInstance3D   # CameraInfo: frustum en 3D (PC: líneas) + Camera3D opcional con la misma óptica.
@export var distancia := 1.0      # profundidad del frustum dibujado (m)
@export var camara: Camera3D      # si se asigna: vista «Camera» de RViz (cámara con la proyección de K)
var _sub: RosSubscriber; var _clave := []

func iniciar(nodo: RosNode, topic: String) -> void:
	var m := StandardMaterial3D.new(); m.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED; m.albedo_color = Color.YELLOW
	material_override = m; mesh = ImmediateMesh.new()
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)
	_sub = nodo.create_subscription(topic, "sensor_msgs/msg/CameraInfo", _on_info, qos)

func _on_info(msg) -> void:
	var k: PackedFloat64Array = msg.k; var w: float = msg.width; var h: float = msg.height
	if k[0] <= 0.0 or [k, w, h] == _clave: return   # sin calibrar o igual que antes: nada que rehacer
	_clave = [k, w, h]
	var esq: Array[Vector3] = []   # esquinas de la imagen proyectadas a «distancia» (óptico → Godot: (x, −y, −z))
	for uv in [Vector2(0, 0), Vector2(w, 0), Vector2(w, h), Vector2(0, h)]:
		esq.append(Vector3((uv.x - k[2]) / k[0], -(uv.y - k[5]) / k[4], -1.0) * distancia)
	var im: ImmediateMesh = mesh; im.clear_surfaces(); im.surface_begin(Mesh.PRIMITIVE_LINES)
	for i in 4:
		for p in [Vector3.ZERO, esq[i], esq[i], esq[(i + 1) % 4]]: im.surface_add_vertex(p)
	im.surface_end()
	if camara:   # frustum descentrado: tamaño y desplazamiento del plano cercano a partir de fy, cx, cy
		var n := camara.near
		camara.keep_aspect = Camera3D.KEEP_HEIGHT
		camara.set_frustum(n * h / k[4], Vector2(n * (w * 0.5 - k[2]) / k[0], n * (k[5] - h * 0.5) / k[4]), n, camara.far)

extends Control   # Display Camera (PC): imagen de fondo + escena vista desde el frame óptico encima.
@export var alfa := 0.5                # RViz Overlay Alpha
@export var fondo: TextureRect         # imagen.gd o comprimida.gd (fondo)
@export var info: Node                 # camara_info.gd con 'camara' = la Camera3D del SubViewport
@export var frame_optico: Node3D       # nodo del frame óptico (TF)
var _vp := SubViewport.new(); var _cam := Camera3D.new(); var _capa := TextureRect.new()

func _ready() -> void:
	_vp.transparent_bg = true; _vp.world_3d = get_viewport().world_3d   # mismo mundo, fondo transparente
	_vp.add_child(_cam); add_child(_vp)
	info.camara = _cam                   # camara_info.gd aplica set_frustum con K
	_capa.texture = _vp.get_texture(); _capa.modulate.a = alfa
	_capa.set_anchors_preset(Control.PRESET_FULL_RECT); add_child(_capa)

func _process(_dt: float) -> void:
	_vp.size = Vector2i(fondo.size)
	if frame_optico: _cam.global_transform = frame_optico.global_transform   # sigue la cámara real

extends MeshInstance3D   # DepthCloud (PC): profundidad + K → nube en la GPU, 0 bucles GDScript por píxel.
@export var paso := 2                 # 1 de cada paso×paso píxeles (diezmado)
@export var color := Color(0.3, 0.9, 1.0)
const SH := "shader_type spatial; render_mode unshaded;
uniform sampler2D prof : filter_nearest; uniform vec4 k; uniform int ancho; uniform int paso; uniform float escala; uniform vec4 col;
void vertex(){ ivec2 px = ivec2(VERTEX_ID % ancho, VERTEX_ID / ancho) * paso;
 float z = texelFetch(prof, px, 0).r * escala;   // 16UC1 unorm → m (escala 65.535) o 32FC1 (escala 1)
 vec3 p = vec3((float(px.x) - k.z) * z / k.x, (float(px.y) - k.w) * z / k.y, z);   // óptico: x der, y abajo, z delante
 VERTEX = z > 0.0 ? vec3(p.x, -p.y, -p.z) : vec3(0.0, 0.0, 1e9);   // a ejes de Godot; sin dato → fuera
 POINT_SIZE = 2.0; }
void fragment(){ ALBEDO = col.rgb; }"
var _subs: Array = []; var _k := Vector4.ZERO; var _mat := ShaderMaterial.new(); var _tex: ImageTexture

func iniciar(nodo: RosNode, topic_prof: String, topic_info: String) -> void:
	_mat.shader = Shader.new(); _mat.shader.code = SH; material_override = _mat
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)
	_subs = [nodo.create_subscription(topic_info, "sensor_msgs/msg/CameraInfo", func(i): _k = Vector4(i.k[0], i.k[4], i.k[2], i.k[5]), qos),
		nodo.create_subscription(topic_prof, "sensor_msgs/msg/Image", _on_prof, qos)]

func _on_prof(msg) -> void:
	if _k == Vector4.ZERO or not (msg.encoding in ["16UC1", "32FC1"]): return
	var fmt := Image.FORMAT_R16 if msg.encoding == "16UC1" else Image.FORMAT_RF
	var img := Image.create_from_data(msg.width, msg.height, false, fmt, msg.data)
	if _tex == null or _tex.get_size() != Vector2(img.get_size()): _tex = ImageTexture.create_from_image(img)
	else: _tex.update(img)
	var w: int = msg.width / paso; var h: int = msg.height / paso
	if mesh == null or mesh.surface_get_array_len(0) != w * h:   # malla de w×h puntos, una sola vez
		var a := []; a.resize(Mesh.ARRAY_MAX); var v := PackedVector3Array(); v.resize(w * h); a[Mesh.ARRAY_VERTEX] = v
		mesh = ArrayMesh.new(); mesh.add_surface_from_arrays(Mesh.PRIMITIVE_POINTS, a); custom_aabb = AABB(Vector3(-50, -50, -50), Vector3(100, 100, 100))
	for p in [["prof", _tex], ["k", _k], ["ancho", w], ["paso", paso], ["escala", 65.535 if fmt == Image.FORMAT_R16 else 1.0], ["col", color]]: _mat.set_shader_parameter(p[0], p[1])
